#include<bits/stdc++.h>
using namespace std;
using PII = pair<int, int>;
const int N = 1e5 + 10, INF = 0x3f3f3f3f;
int n, res;
vector<PII> v;

bool cmp(PII p1, PII p2) {
	return p1.second < p2.second;
}

int main(){
	cin >> n;
	for (int i = 0;i < n;i++) {
		int a, b;cin >> a >> b;
		v.push_back({ a,b });
	}
	sort(v.begin(), v.end(), cmp);
	int cur = ~INF;
	for (int i = 0;i < n;i++) {
		if (cur < v[i].first) {
			cur = v[i].second;
			res++;
		}
	}
	cout << res;
}
